function valueLabel(week, value) {
  if (value === null || value === undefined) return '미입력';
  if (isDumbbell(week)) return dumbbellValueLabel(week, value);
  if (week?.inputType === 'walking') return bands[value] ?? '구간 확인 필요';
  if (typeof value === 'boolean') return [2,11].includes(week?.week) ? (value ? '했음' : '안 했음') : (value ? '기준 충족' : '미충족');
  if (week?.deferred) return '세부 기준 확정 대기';
  return `${fmt(value)}${week?.unit || ''}`;
}
