    {error&&<ErrorNotice error={error}/>}
    <div className={mobile?'mt24':'w-grid mt24'} style={mobile?undefined:{gridTemplateColumns:'minmax(0,1fr) 380px'}}><div><div className="sec-t">{mobile?'주차별':'주차별 현황'}</div>{mobile?<div className="list mt12">{weeks.map(w=>{const s=summary.weeks.find(x=>x.week===w.week);return <button className="li link" style={{width:'100%',textAlign:'left'}} key={w.week} onClick={()=>{setWeekNumber(w.week);setDialog('week')}}><div className={'ico-wrap '+(s.complete===true?'g':'')} style={{width:36,height:36,borderRadius:12}}><Icon name={s.complete===true?'check':'calendar'}/></div><div className="grow"><div className="k fs14">{w.week}주차 · {w.title}</div><div className="sub">{weekLabel(w)}</div></div>{w.startDate>program.data.today?<span className="chip line">예정</span>:<StateChip summary={s}/>}</button>})}</div>:<div className="tbl-wrap mt12"><table className="tbl"><thead><tr><th>주차</th><th>목표</th><th>평일</th><th>주말</th><th>합계</th><th>결과</th></tr></thead><tbody>{weeks.map(w=>{const s=summary.weeks.find(x=>x.week===w.week),future=w.startDate>program.data.today;return <tr key={w.week} className={weekNumber===w.week?'sel':''} tabIndex={0} onClick={()=>setWeekNumber(w.week)} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();setWeekNumber(w.week)}}} style={{cursor:'pointer'}}><td><div className="row gap8"><i style={{width:9,height:9,borderRadius:3,background:w.color,display:'inline-block'}}/><b className={future?'muted':''}>{w.week}주차 · {w.title}</b></div></td><td className="muted"><Goal week={w}/></td><td className="num-font">{s.weekdayTotal===null||future?'—':fmt(s.weekdayTotal)+w.unit}</td><td className="num-font">{s.weekendTotal===null||future?'—':s.makeupDays!==null?'보충 '+s.makeupDays+'일':fmt(s.weekendTotal)+w.unit}</td><td className="num-font fw7">{s.total===null||future?'—':fmt(s.total)+' / '+fmt(w.weeklyTarget)+w.unit}</td><td>{future?<span className="chip line">예정</span>:<StateChip summary={s}/>}</td></tr>})}</tbody></table></div>}</div>{!mobile&&<div className="sticky"><div className="sec-t">{weekNumber}주차 날짜별</div>{days}</div>}</div>
    {mobile&&<div className="row gap8 mt16"><button className="btn secondary grow" onClick={()=>setDialog('edit')}>정보 수정</button><button className="btn secondary grow" onClick={()=>setDialog('reset')}>비밀번호 초기화</button></div>}
    {dialog==='week'&&<Modal title={weekNumber+'주차 · '+week.title} onClose={()=>setDialog(null)}>{days}</Modal>}
    {dialog==='edit'&&<StudentForm student={student} onClose={()=>setDialog(null)} onSaved={()=>{setDialog(null);setRevision(v=>v+1)}}/>}
