  const rejectDialog=reject&&<Modal title="반려 사유" onClose={busy?undefined:()=>setReject(null)} footer={<><button className="btn secondary" disabled={busy} onClick={()=>setReject(null)}>취소</button><button className="btn danger" disabled={busy||!reason.trim()} onClick={()=>decide('reject',reject)}>반려하기</button></>}><p className="fs13 muted mt8">{(reject.student||reject.user)?.name} 학생에게 전달할 사유를 입력해 주세요.</p><textarea className="textarea mt16" disabled={busy} style={{width:'100%',minHeight:120}} value={reason} onChange={e=>setReason(e.target.value)} placeholder="반려 사유를 입력하세요."/>{error&&<ErrorNotice error={error}/>}</Modal>;
